class EducationScreen extends StatelessWidget { const EducationScreen({super.key}); static const topics=[('Eczema','Dry, itchy, inflamed skin can have many causes. Gentle moisturizers and avoiding personal triggers may help.'),('Psoriasis','Psoriasis is a long-term inflammatory condition. A clinician can assess symptoms and discuss treatment.'),('Acne','Acne is common and varies from person to person. Avoid harsh scrubbing and seek care for persistent or painful acne.'),('Dry skin','Dryness can be affected by weather, bathing, and products. Persistent cracking or discomfort may need medical advice.'),('Sun safety','Use shade, protective clothing, and broad-spectrum sunscreen. Check your skin and ask a clinician about changes.')]; @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Skin learning hub')),body:ListView(padding:const EdgeInsets.all(16),children:[const NoticeBanner(),const SizedBox(height:12),...topics.map((e)=>Card(child:ExpansionTile(leading:const Icon(Icons.spa_outlined),title:Text(e.$1),childrenPadding:const EdgeInsets.fromLTRB(20,0,20,18),children:[Text(e.$2)]))),const SizedBox(height:12),Card(child:ListTile(leading:const Icon(Icons.emergency_outlined,color:Colors.red),title:const Text('When to get urgent help'),subtitle:const Text('Seek urgent medical help for severe pain, rapidly spreading redness, high fever, or serious allergic symptoms.')))]));}
